    return {
        init:          init,
        update:        update,
        spawn:         spawn,
        spawnForLevel: spawnForLevel,
        explode:       explode,
        reset:         reset,
        hitBarrel:     hitBarrel,
        kickBarrel:    kickBarrel,
        isOnOilSlick:  isOnOilSlick,
        TYPES:         BARREL_TYPES
    };
