    var helmGeo = new THREE.BoxGeometry(0.38, 0.2, 0.38);
    var helmMat = new THREE.MeshLambertMaterial({ color: 0x3d4a2a }); // dark camo
    var helm = new THREE.Mesh(helmGeo, helmMat);
