      // Seeded fallback: 3-5 documents
      var idStr = String(levelId);
      var seedBase = 0;
      for (var ci = 0; ci < idStr.length; ci++) {
        seedBase += idStr.charCodeAt(ci) * (ci + 7);
      }
      var count = 3 + (Math.abs(seedBase) % 3); // 3, 4, or 5
