      'top:60px',
      'left:50%',
      'transform:translateX(-50%)',
      'background:rgba(0,0,0,0.7)',
      'color:#ffd700',
      'font-family:monospace',
      'font-size:15px',
      'font-weight:bold',
      'padding:4px 14px',
      'border:1px solid #ffd700',
