    var dirX = Math.cos(angle);
    var dirZ = Math.sin(angle);
    var wireLength = 4.0;

    var wirePoints = [];
    wirePoints.push(new THREE.Vector3(0, 0.08, 0));
    wirePoints.push(new THREE.Vector3(dirX * wireLength, 0.08, dirZ * wireLength));
