              _scene.remove(ied.group);
              _disarmHoldTime = 0;
              _disarmTarget   = null;
              _eKeyHeld       = false;
              _hideDisarmBar();
              _toast('💣 IED disarmed — charge refunded', '#a8c060');
              _updateHUD();
