    for (var ri = toRemove.length - 1; ri >= 0; ri--) {
      _ieds.splice(toRemove[ri], 1);
    }

    // Reset disarm target if E not held
    if (!_eKeyHeld && _disarmTarget !== null) {
      _disarmTarget   = null;
      _disarmHoldTime = 0;
      _hideDisarmBar();
    }

