    _blinkTimer  = 0;
    _blinkState  = false;
    _slowTimer   = 0;
    _slowState   = false;
    _disarmHoldTime = 0;
    _disarmTarget   = null;
    _eKeyHeld       = false;
    _ctrlHeld       = false;
