  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  return {
    init:                init,
    showMissionComplete: showMissionComplete,
    showMissionFailed:   showMissionFailed
  };

